INSERT INTO transfer_targets VALUES(10,'2026-summer','Modou Kéba Cissé','시세',1944705,'LASK → Aston Villa','CB','RCB','CONFIRMED','00200001420237413X9814X84',60.89999999999999858,31.19999999999999929,6,6.769999999999999574,'cb_defender','Balanced','cb_bpd','Aggressive',0.8900000000000000133,'CONFIRMED incoming: pre-contract signed summer 2025, joins for 2026/27 after a season at LASK. Measured: right-of-centre CB (60.9,31.2), Ball-Playing Defender/Aggressive fit 0.89 — same fit family as Konsa (0.88). Natural RCB cover/heir; Austrian Bundesliga level caveat. [2026-07-15 재확인] RotoWire: 공식 합류 확인(사전계약, LASK에서 2026년 여름 발효). [2026-07-15 3축+스탯 — 유지] 6경기: kp 0·xA .01·듀얼 3.8·태클 1.5·패스 84% — 진전 산출 없는 수비형, cb_defender/Balanced 처방 유지(움직임은 bpd/Aggressive .89로 콘사형 스텝아웃 — 기능축 우선). LASK 리그 수준 캐비앗.','https://readastonvilla.com/2026/05/14/modou-keba-cisse-the-future-aston-villa-player-who-is-shining-in-austria/ ; SofaScore API player 1944705 (2026-07-02)','CONFIRMED signing; measured from LASK (league-strength caveat). / 2026-07-15: 공식 완료 확인 — CONFIRMED 유지.','시세');
INSERT INTO transfer_targets VALUES(13,'2026-summer','Alysson','알리송',1631879,'Aston Villa (2026-01, Grêmio €10M)','RW','RM','OWNED','001640014X000380003600011',83.20000000000000284,59.70000000000000284,6,6.75,'wm_winger','Attack','wm_insidefwd','Balanced',0.8469999999999999752,'ALREADY OWNED: joined from Grêmio for €10M in January 2026; young (2006) right winger not yet in the analysis roster. Measured: genuine wide-right (83.2,59.7) — the squad''s only natural touchline RW; fit Inside Forward/Balanced 0.85. Prescription Winger/Attack to use his width+pace profile distinct from McGinn/Bowen half-space types. [2026-07-15 3축+스탯 — 유지] 6경기: xG .10·xA .03·kp .3·듀얼 3.7·드리블 1.0 — 창조 산출 미성숙 직선 윙어, winger/Attack 처방 유지(움직임 최근접은 insidefwd/Balanced .847).','https://www.fotmob.com/teams/10252/transfers/aston-villa ; SofaScore API player 1631879 (2026-07-02)','OWNED; measured mixes Grêmio+Villa minutes (sample caveat).',NULL);
INSERT INTO transfer_targets VALUES(18,'2026-summer','Anis Hadj Moussa','하지 무사',1218066,'Feyenoord','RW','RM','MEDIUM-HIGH','312691114X000140002400001',76.90000000000000569,69.29999999999999716,6,7.549999999999999823,'wm_insidefwd','Attack','wm_insidefwd','Attack',0.923000000000000042,'ADVANCE TALKS (Villa vs Newcastle); player prioritising a PL move for 26/27, Feyenoord ask ~€35m. Measured: high-and-wide right winger (76.9,69.3), Inside Forward/Attack fit 0.92 — the HIGHEST RM-slot fit sampled (Bowen 0.88) AND the highest avg rating of all targets (7.55). Eredivisie level caveat. [2026-07-03 watch: talks well underway with both Villa & Newcastle, expected to accelerate; Newcastle edge — Villa CL squad-registration restriction (UEFA fine) may hamper. Feyenoord ~€35m. Grade unchanged.] [2026-07-09 watch: TransferFeed/Yahoo — 빌라·뉴캐슬이 "most advanced in discussions" 공식 표현으로 보도, 선수 본인도 PL 선호 재확인. MEDIUM-HIGH에서 HIGH 상향.] [2026-07-15 재확인] Sacha Tavolieri(2티어급): "advanced talks" 보도 재확인, 대리인이 빌라·뉴캐슬 지목. 페예노르트 €35m 고수. [2026-07-15 3축+스탯 — 교정 winger/Attack→insidefwd/Attack] 6경기 스탯: xG .42·xA .46·kp 3.2·드리블 2.0·3골(평점 7.50 후보군 1위). 기능=득점+창조 양방 엘리트 = 컷인형 인사이드 포워드. 현커널 움직임도 insidefwd/Attack .923 최상 — 2축 일치로 교정. [2026-07-19 재검증] advanced talks 근거였던 Sky Sport Switzerland(Tavolieri)는 영국 Sky Sports 공식(tier-1)과 별개 매체로 재분류 — HIGH 유지 근거 약화. 선덜랜드 신규 문의·첼시 모니터링으로 경쟁 확대.','https://thehardtackle.com/transfer-news/2026/06/30/aston-villa-newcastle-united-advance-talks-to-sign-anis-hadj-moussa/ ; SofaScore API player 1218066 (2026-07-02)','MEDIUM-HIGH — [2026-07-26 재검증] Tavolieri(2티어) 협상 진전 + 에이전트 다흐마네 "PL 희망, 빌라·뉴캐슬 관심" 공개 확인(7/2-3). 페예노르트 €35m. 선덜랜드 문의 가세.','하지무사');
INSERT INTO transfer_targets VALUES(30,'2026-summer','Tammy Abraham','타미 아브라함',610766,'Aston Villa','ST','ST','OWNED','01855255648X8415422010200',47.39999999999999858,59.0,4,6.849999999999999645,'st_target','Attack','st_false9','Attack',0.5210000000000000186,'ALREADY OWNED: 2026-01-27 베식타슈에서 ~£18m로 빌라 복귀(1일 만에 재이적), 그 시즌 유로파리그 우승. 여름 루머 대상이 아니라 보유 선수(알리송과 동일 케이스) — 사용자 요청으로 OWNED ST 옵션으로 편입. 실측(반시즌 통틀어 45분+ 4경기 전부 ST): 중앙-약간좌측·깊은 풋프린트 (47.4,59.0), 평균 6.85. 최근접 st_false9/Attack 0.52 — 왓킨스(st_advanced 자기커널)·기라시 0.80·브로베이 0.75·파르도 0.87보다 명확히 낮음. 처방은 타깃/홀드업 아키타입 반영 st_target/Attack. 표본 캐비앳: 왓킨스의 로테이션 백업이라 45분+ 경기가 반시즌 4경기뿐이고 전부 교체 출전(추격 상황 드롭) → 깊은 편향된 풋프린트, 선발 표본 아님. [2026-07-15 3축+스탯 — 유지] 6경기: xG .25·3골·kp 1.0·드리블 0 — 타깃형 피니셔, st_target/Attack(공중 플랜B, obs#19) 유지.','https://www.avfc.co.uk/news/2026/january/27/signing-aston-villa-confirm-tammy-abraham-signing/ ; SofaScore API player 610766 (2026-07-03)','OWNED — 이적 루머 아님(2026-01 합류확정 보유선수). 측정 신뢰 MEDIUM(표본 4경기·전부 교체출전·맥락 편향, 45분+ 6경기 미달).',NULL);
INSERT INTO transfer_targets VALUES(46,'2026-summer','Ibrahim Mbaye','이브라힘 음바예',1590918,'Paris Saint-Germain','FW','RM','MEDIUM-HIGH','001231104X000160001200000',75.79999999999999716,65.09999999999999431,243,6.919999999999999929,'wm_insidefwd','Balanced','wm_insidefwd','Balanced',0.958999999999999964,'측정 6경기(45분+, 2026-02-01~2026-07-01 확장표본 — PSG 로테이션/조커 자원이라 최근 30일 내 45분+ 경기가 부족해 리그1·챔피언스리그·월드컵·평가전으로 기간 확장, Fernández-Pardo 사례와 동일 방식): 우측 전진 배치(중심 tool_x=75.8, tool_y=65.1) — RM/RW 우측 인버티드 성향. 평균 평점 6.92. wm_insidefwd/Balanced 핏 0.959로 RM 슬롯 후보 중 최고 수준. 세계 최연소 월드컵 아프리카 득점자(vs 프랑스, 테오 에르난데스 제치고 득점)로 부각, PSG는 2028년까지 계약이라 매각 압박 없음. 빌라 £34m(€40m) 오퍼 준비설. [2026-07-15 재확인] TeamTalk: PSG 등 6개 클럽 컨택 확인, 빌라가 선두로 치고 나간 정황. "합의 임박" 보도는 저신뢰 소스발이라 유보적으로 반영. [2026-07-15 3축+스탯 — focus 교정 Attack→Balanced] 6경기 스탯: xG .27·xA .19·kp 1.2·드리블 1.3·패스 87%. 기능=득점·창조 균형(양방), 움직임도 insidefwd/Balanced .959 압도적 최상(Attack은 <.84) — Balanced가 정확. [2026-07-19 재검증] Romano(1티어) PSG 이탈 확정·멘드스 에이전트 선임 재확인, 다수 PL 클럽 경쟁 중 빌라 포함. 맨시티 하이잭 위협 신규 등장, 토트넘도 지속 경쟁 — 등급 유지. [2026-07-20 21시(4차) 재검증] TeamTalk(2티어): PSG가 오퍼에 열려있으며 빌라 포함 PL 6개 클럽 경쟁 — 경쟁 클럽 수 확대는 희석 신호. Romano발 신규 진전 없음. 등급 유지, 경쟁 심화를 리스크로 병기. [2026-07-21 예산 분석] €40-50m — 배정 범위 상한 부근이나 소화 가능. 유지.','https://api.sofascore.com/api/v1/player/1590918 (SofaScore API 실측, 2026-07-08) ; https://www.sportsmole.co.uk/football/aston-villa/transfer-talk/news/aston-villa-in-pole-position-for-psg-teenager-who-became-world-cup-history-maker_600822.html ; https://www.caughtoffside.com/2026/07/07/aston-villa-tottenham-circle-psg-wonderkid/ ; https://www.givemesport.com/aston-villa-frontrunners-sign-psg-ibrahim-mbaye/','MEDIUM-HIGH — [2026-07-26 재검증, 상향 후보] Athletic "로저스 대체 우선 타깃" + Romano PSG 이탈 방침 확인(1티어 복수). PSG 밸류 €40-50m, 오퍼에 열려있음(7/17). 협상·합의 단계는 아직.','음바예');
INSERT INTO transfer_targets VALUES(75,'2026-summer','Pervis Estupiñán','에스투피냔',805465,'AC Milan','LB','LB','HIGH','21000X3100610007200032100',16.10000000000000143,49.10000000000000142,6,6.870000000000000106,'fb_att_wb','Support','fb_att_wb','Support',0.945999999999999953,'좌측면 전 깊이 커버 공격형 레프트백. 실측 6경기(세리에A, 322pt) 중심 tool(16,49). 커널 fit fb_att_wb/Support 0.946 (2위 fb_inverted/Build-Up 0.89). 밀란 아모림 구상 외, 호가 ~€14m. [2026-07-14 야간 재확인] Romano: "AVFC 좌측백 3인 숏리스트 중 상위, 딜 진행중, 협상 계속"(YouTube) — 단 조건 미확정, 데포르티보 라코루냐 경쟁 참전. 디뉴 대체가 아니라 마첸 백업/뎁스 역할로 영입(주전 보장 아님). [2026-07-15 재확인] Matteo Moretto(로마노 채널, 준1티어급): "협상 공식 개시" 확인 — 밀란-빌라 간 클럽 대 클럽 협상 단계 진입. 이적료 격차(€18-20m vs €10-12m)만 남음. 협상 단계 확인으로 HIGH 상향. [2026-07-15 3축+스탯 — 유지] 6경기: 패스 89%·태클 1.3·kp .8 — 견실 전진 LB. att_wb/Support 유지(마첸 07-15 교정 처방과 동일 — 경쟁 구도 명확). [2026-07-17 재확인] Romano(1티어): 개인조건 합의 완료. 클럽간 협상 advanced("non-stop contacts" — Longo), 이적료 격차 €12m vs €18-20m에서 Gazzetta €15m 절충설. 완료 임박 국면. [2026-07-18 재확인] 클럽간 최종 협상 단계 — 밀란 €18-20m vs 빌라 €10-12m에서 €15m 절충 근접(Gazzetta), "다음 주 초 이전 타결" 양측 낙관. 결정적 미팅 수일 내. [2026-07-19 재검증 강화] Romano(1티어, 7/16-17): 빌라가 에스투피냔과 개인조건 합의, 선수도 이적 희망, AC밀란과 이적료 협상 계속. 텔레그래프(2티어)도 advanced 확인. 이적료 격차만 남음(18-20m 밀란 요구 vs 10-13m대 빌라).','Moretto via SempreMilan https://sempremilan.com/moretto-aston-villa-enquire-milan-estupinan ; SofaScore player/805465 (6 Serie A ~2026-05-10) ; milanreports 7/21·7/23 (Athletic·Tuttosport 경유, 재검증 07-26)','HIGH — [2026-07-26 재검증] Athletic(1티어) 개인합의+이적료 협상(빌라 €15m vs 밀란 €18-20m). ★리스크: 7/23 Tuttosport — 아모림 직접 평가 원해 딜 standby, 메디컬 미실시.','에스투피냔');
